171	    /// Removes and returns the message with this arrival index.
172	    pub fn remove(&mut self, key: u64) -> Option<Message> {
173	        let message = self.messages.remove(&key)?;
174	        if let Some(handle) = message.handle {
175	            self.handles.remove(&handle);
176	        }
177	        Some(message)
178	    }
179	
180	    /// The arrival index of the message that is in flight right now and whose
181	    /// latest handle is `handle`.
182	    pub fn find_in_flight(&self, handle: u64, now: u64) -> Option<u64> {
183	        let key = *self.handles.get(&handle)?;
