195	        let mut steps = Vec::new();
196	        let mut delivered = 0;
197	        // Groups that still have an earlier message in the queue.
198	        let mut blocked: HashSet<&str> = HashSet::new();
199	        for (&key, message) in &self.messages {
200	            let group = message.group_id.as_deref();
201	            if group.is_some_and(|g| blocked.contains(g)) {
