203	            }
204	            if message.state(now) != State::Visible {
205	                blocked.extend(group);
206	                continue;
207	            }
208	            match &self.attributes.dead_letter {
209	                Some(dl) if message.receive_count >= dl.max_receive_count => {
210	                    steps.push(Step::DeadLetter(key));
211	                }
212	                _ => {
213	                    steps.push(Step::Deliver(key));
214	                    blocked.extend(group);
215	                    delivered += 1;
216	                    if delivered == max_messages {
217	                        break;
218	                    }
219	                }
220	            }
221	        }
222	        steps
223	    }
224	
225	    /// Delivers a message: it is now in flight for `visibility_timeout`
226	    /// seconds under the new receipt `handle`.
227	    pub fn deliver(
228	        &mut self,
229	        key: u64,
230	        now: u64,
231	        visibility_timeout: u64,
232	        handle: u64,
233	    ) -> &Message {
234	        let message = self.messages.get_mut(&key).expect("planned message exists");
235	        if let Some(old) = message.handle.replace(handle) {
236	            self.handles.remove(&old);
237	        }
238	        self.handles.insert(handle, key);
239	        message.receive_count += 1;
240	        message.first_received_at.get_or_insert(now);
241	        message.invisible_until = now + visibility_timeout;
242	        message
243	    }
244	
245	    /// The original send of this deduplication id, if its window is open.
246	    pub fn duplicate_of(&self, deduplication_id: &str, now: u64) -> Option<Accepted> {
247	        self.deduplication
248	            .get(deduplication_id)
249	            .filter(|a| now - a.accepted_at < DEDUP_WINDOW)
250	            .copied()
251	    }
252	
253	    /// Opens a deduplication window for an accepted send.
254	    pub fn record_deduplication(&mut self, deduplication_id: &str, accepted: Accepted) {
255	        if self.deduplication.len() >= self.prune_deduplication_at {
256	            let now = accepted.accepted_at;
257	            self.deduplication
258	                .retain(|_, a| now - a.accepted_at < DEDUP_WINDOW);
259	            self.prune_deduplication_at = (self.deduplication.len() * 2).max(MIN_DEDUP_PRUNE_LEN);
260	        }
261	        self.deduplication
262	            .insert(deduplication_id.to_owned(), accepted);
263	    }
264	}
